ci_existing_evidence_valid() {
	local ticket_id="$1"
	local dir="$ROOT/$EVIDENCE_DIR/$ticket_id"
	local manifest="$dir/manifest.json"
	[[ -s "$manifest" ]] || return 1
	command -v python3 >/dev/null 2>&1 || return 1

